window.__PAGE_RUNTIME_PARTIALS__["partials/taller-integrador-sb11-content.html"] = "\u003cbutton class=\"hamburger\" onclick=\"toggleSidebar()\" aria-label=\"Menú\"\u003e\u0026#9776;\u003c/button\u003e\n\u003cbutton class=\"btn-sb-expand\" onclick=\"showSidebar()\" title=\"Mostrar barra lateral\"\u003e\u0026#9776;\u003c/button\u003e\n\n\u003cdiv class=\"layout app-layout\"\u003e\n  \u003cnav class=\"sidebar\" id=\"sidebar\"\u003e\n    \u003cdiv class=\"sidebar-logo\"\u003e\n      \u003cdiv class=\"badge\"\u003eSENA · FPI\u003c/div\u003e\n      \u003ch2\u003eTaller Integrador\u003c/h2\u003e\n      \u003cp\u003eSistemas Teleinformáticos\u003c/p\u003e\n      \u003cbutton class=\"btn-sb-collapse\" onclick=\"hideSidebar()\" title=\"Ocultar barra lateral\"\u003e\u0026#9664;\u003c/button\u003e\n    \u003c/div\u003e\n\n    \u003cdiv class=\"sidebar-ficha\" id=\"sb-ficha-ok\" style=\"display:none\"\u003e\n      \u003cdiv class=\"sf-label\"\u003eTu grupo\u003c/div\u003e\n      \u003cdiv class=\"sf-inst\" id=\"sb-inst\"\u003e\u003c/div\u003e\n      \u003cdiv class=\"sf-meta\" id=\"sb-grupo-meta\"\u003e\u003c/div\u003e\n      \u003cdiv class=\"sf-badge\" id=\"sb-badge\"\u003e\u003c/div\u003e\n    \u003c/div\u003e\n    \u003cdiv class=\"sidebar-noficha\" id=\"sb-ficha-warn\"\u003e\n      \u003ca href=\"index.html\"\u003eInicio | Seleccionar grupo / ficha\u003c/a\u003e\n    \u003c/div\u003e\n\n    \u003cdiv class=\"progress-wrap\"\u003e\n      \u003cdiv class=\"progress-label\"\u003e\n        \u003cspan\u003eProgreso\u003c/span\u003e\n        \u003cspan id=\"progressValue\"\u003e0%\u003c/span\u003e\n      \u003c/div\u003e\n      \u003cdiv class=\"progress-bar-bg\"\u003e\n        \u003cdiv class=\"progress-bar\" id=\"progressBar\"\u003e\u003c/div\u003e\n      \u003c/div\u003e\n      \u003cp class=\"progress-note\"\u003eEl avance se guarda localmente en este navegador.\u003c/p\u003e\n      \u003cbutton type=\"button\" class=\"reset-button\" id=\"resetProgress\"\u003eReiniciar respuestas\u003c/button\u003e\n    \u003c/div\u003e\n\n    \u003cdiv class=\"nav-section\"\u003e\n      \u003cdiv class=\"nav-label\"\u003eInformación\u003c/div\u003e\n      \u003ca class=\"nav-link active\" href=\"#identificacion\" onclick=\"setActive(this)\"\u003e\n        \u003cspan class=\"icon\"\u003e\u0026#128203;\u003c/span\u003e Identificación\n      \u003c/a\u003e\n      \u003ca class=\"nav-link\" href=\"#control-avance\" onclick=\"setActive(this)\"\u003e\n        \u003cspan class=\"icon\"\u003e\u0026#9989;\u003c/span\u003e Control de avance\n      \u003c/a\u003e\n      \u003ca class=\"nav-link\" href=\"#presentacion\" onclick=\"setActive(this)\"\u003e\n        \u003cspan class=\"icon\"\u003e\u0026#128075;\u003c/span\u003e Presentación\n      \u003c/a\u003e\n      \u003ca class=\"nav-link\" href=\"#equipo\" onclick=\"setActive(this)\"\u003e\n        \u003cspan class=\"icon\"\u003e\u0026#128101;\u003c/span\u003e Tu equipo\n      \u003c/a\u003e\n    \u003c/div\u003e\n\n    \u003cdiv class=\"nav-section\"\u003e\n      \u003cdiv class=\"nav-label\"\u003eProductos del taller\u003c/div\u003e\n      \u003ca class=\"nav-link\" href=\"#producto1\" onclick=\"setActive(this)\"\u003e\n        \u003cspan class=\"icon\"\u003e1\u0026#65039;\u0026#8419;\u003c/span\u003e Informe de infraestructura\n        \u003cspan class=\"check\"\u003e\u0026#10003;\u003c/span\u003e\n      \u003c/a\u003e\n      \u003ca class=\"nav-link\" href=\"#producto2\" onclick=\"setActive(this)\"\u003e\n        \u003cspan class=\"icon\"\u003e2\u0026#65039;\u0026#8419;\u003c/span\u003e Plan de mejora\n        \u003cspan class=\"check\"\u003e\u0026#10003;\u003c/span\u003e\n      \u003c/a\u003e\n      \u003ca class=\"nav-link\" href=\"#producto3\" onclick=\"setActive(this)\"\u003e\n        \u003cspan class=\"icon\"\u003e3\u0026#65039;\u0026#8419;\u003c/span\u003e Informe de ejecución\n        \u003cspan class=\"check\"\u003e\u0026#10003;\u003c/span\u003e\n      \u003c/a\u003e\n      \u003ca class=\"nav-link\" href=\"#producto4\" onclick=\"setActive(this)\"\u003e\n        \u003cspan class=\"icon\"\u003e4\u0026#65039;\u0026#8419;\u003c/span\u003e Reporte de cumplimiento\n        \u003cspan class=\"check\"\u003e\u0026#10003;\u003c/span\u003e\n      \u003c/a\u003e\n    \u003c/div\u003e\n\n    \u003cdiv class=\"nav-section\"\u003e\n      \u003cdiv class=\"nav-label\"\u003eEntrega\u003c/div\u003e\n      \u003ca class=\"nav-link\" href=\"#requisitos\" onclick=\"setActive(this)\"\u003e\n        \u003cspan class=\"icon\"\u003e\u0026#128196;\u003c/span\u003e Requisitos formales\n      \u003c/a\u003e\n      \u003ca class=\"nav-link\" href=\"#fechas\" onclick=\"setActive(this)\"\u003e\n        \u003cspan class=\"icon\"\u003e\u0026#128197;\u003c/span\u003e Fechas de entrega\n      \u003c/a\u003e\n      \u003ca class=\"nav-link\" href=\"#evaluacion\" onclick=\"setActive(this)\"\u003e\n        \u003cspan class=\"icon\"\u003e\u0026#127919;\u003c/span\u003e Evaluación\n      \u003c/a\u003e\n    \u003c/div\u003e\n\n    \u003cdiv class=\"nav-section\"\u003e\n      \u003cdiv class=\"nav-label\"\u003eTaller asignado\u003c/div\u003e\n      \u003ca class=\"nav-guide current\" id=\"currentGuideNavLink\" href=\"grupo-11a-guia-09-taller-integrador.html\" data-current-file=\"grupo-11a-guia-09-taller-integrador.html\"\u003e\n        \u003cspan class=\"g-icon\"\u003e\u0026#128215;\u003c/span\u003e\n        \u003cspan class=\"g-info\"\u003e\n          \u003cspan class=\"g-num\"\u003eTaller\u003c/span\u003e\n          \u003cspan class=\"g-name\" id=\"currentGuideNavLabel\"\u003eTaller Integrador | 11A\u003c/span\u003e\n        \u003c/span\u003e\n        \u003cspan class=\"g-tag actual\"\u003eActual\u003c/span\u003e\n      \u003c/a\u003e\n    \u003c/div\u003e\n\n    \u003ca class=\"nav-home-link\" href=\"calendario-academico-2026.html\"\u003e\u0026#128197; \u003cspan\u003eCalendario 2026\u003c/span\u003e\u003c/a\u003e\n    \u003ca class=\"nav-home-link\" href=\"index.html\"\u003e\u0026#127968; \u003cspan\u003eVolver al Inicio\u003c/span\u003e\u003c/a\u003e\n  \u003c/nav\u003e\n\n  \u003cmain class=\"main app-main\"\u003e\n    \u003cdiv class=\"topbar\"\u003e\n      \u003cdiv class=\"topbar-title\"\u003e\n        \u003cstrong\u003eTaller Integrador\u003c/strong\u003e\n      \u003c/div\u003e\n      \u003cdiv class=\"topbar-meta\"\u003e\n        \u003cspan class=\"meta-item\"\u003e\u003cspan\u003e\u0026#9201;\u003c/span\u003e\u003cspan\u003eTodo el año lectivo\u003c/span\u003e\u003c/span\u003e\n        \u003cspan class=\"meta-item\"\u003e\u003cspan\u003e\u0026#128197;\u003c/span\u003e\u003cspan\u003e2026\u003c/span\u003e\u003c/span\u003e\n        \u003cspan class=\"meta-item\"\u003e\u003cspan\u003e\u0026#127979;\u003c/span\u003e\u003cspan id=\"topbarCampus\"\u003eSanta Bárbara | 11A\u003c/span\u003e\u003c/span\u003e\n      \u003c/div\u003e\n    \u003c/div\u003e\n\n    \u003cdiv class=\"content\"\u003e\n      \u003cdiv class=\"hero\" id=\"inicio\"\u003e\n        \u003cdiv class=\"tag\"\u003eProyecto integrador de cierre\u003c/div\u003e\n        \u003ch1\u003eTaller Integrador\u003c/h1\u003e\n        \u003cp\u003e\n          Vas a poner en práctica todo lo aprendido en el programa: vas a diagnosticar,\n          planear, ejecutar y validar el mantenimiento de equipos de cómputo y redes de datos\n          de una micro, pequeña o mediana empresa (MiPyme) real de la región de Boyacá, y vas a\n          dejar evidencia escrita de todo el proceso.\n        \u003c/p\u003e\n        \u003cdiv class=\"hero-meta\"\u003e\n          \u003cdiv class=\"hero-meta-item\"\u003e\u0026#127963; SENA \u0026mdash; Servicio Nacional de Aprendizaje\u003c/div\u003e\n          \u003cdiv class=\"hero-meta-item\"\u003e\u0026#128205; Institución Educativa Santa Bárbara \u0026middot; Grupos 11°A y 11°B\u003c/div\u003e\n          \u003cdiv class=\"hero-meta-item\"\u003e\u0026#128101; Trabajo en equipos de 3 a 4 aprendices\u003c/div\u003e\n          \u003cdiv class=\"hero-meta-item\"\u003e\u0026#128196; Entrega escrita, sin sustentación oral\u003c/div\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003cdiv class=\"gnote gnote--recuerda\" style=\"margin-top:16px\"\u003e\n        \u003cdiv class=\"gnote__label\"\u003e\u0026#9888; Último año de este grupo\u003c/div\u003e\n        \u003cp\u003eEste es el \u003cstrong\u003eúltimo año de contrato\u003c/strong\u003e de los grupos 11°A y 11°B (finaliza el\n        30 de noviembre de 2026). A diferencia de otros talleres, aquí \u003cstrong\u003eno hay grado 12° al que\n        trasladar pendientes\u003c/strong\u003e: el Producto 4 (entrega final) debe quedar cerrado dentro del\n        Corte 4, sin excepción.\u003c/p\u003e\n      \u003c/div\u003e\n\n      \u003cdiv id=\"control-avance\" class=\"section-title\"\u003eTu control de avance\u003c/div\u003e\n      \u003cdiv class=\"card open\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon\" style=\"background:#e8f5e9\"\u003e\u0026#9989;\u003c/div\u003e\n            \u003cdiv\u003e\u003ch3\u003e\u0026iquest;Qué llevas y qué te falta?\u003c/h3\u003e\u003cp\u003eSe actualiza solo con tus propias entregas a Drive\u003c/p\u003e\u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003cdiv data-act-std-avance\u003e\u003cp class=\"intro-text\"\u003eCargando tu avance...\u003c/p\u003e\u003c/div\u003e\n          \u003cdiv class=\"gnote gnote--recuerda\"\u003e\u003cdiv class=\"gnote__label\"\u003e\u0026#128161; Recuerda\u003c/div\u003e\n            \u003cp\u003eEsta tabla es \u003cstrong\u003epor cuenta\u003c/strong\u003e: se marca \u003cstrong\u003eEntregada\u003c/strong\u003e cuando\n            \u003cem\u003etú\u003c/em\u003e subes el producto a Drive desde tu usuario, aunque el documento sea el mismo para\n            todo el equipo. Cada integrante debe entregarlo también desde su propia cuenta para que su\n            avance quede en Entregada.\u003c/p\u003e\u003c/div\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003cdiv id=\"identificacion\" class=\"section-title\"\u003eIdentificación del Taller\u003c/div\u003e\n      \u003cdiv class=\"card open\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon\" style=\"background:#e8f5e9\"\u003e\u0026#128203;\u003c/div\u003e\n            \u003cdiv\u003e\n              \u003ch3\u003eDatos generales\u003c/h3\u003e\n              \u003cp\u003eInformación oficial del taller integrador\u003c/p\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003cdiv class=\"table-scroll\"\u003e\n            \u003ctable class=\"data-table ident-table\"\u003e\n              \u003ctbody\u003e\n                \u003ctr\u003e\u003ctd\u003eDenominación del Programa\u003c/td\u003e\u003ctd\u003eSistemas Teleinformáticos\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eNombre del proyecto\u003c/td\u003e\u003ctd\u003eTaller Integrador\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eInstitución educativa\u003c/td\u003e\u003ctd\u003eSanta Bárbara (SB)\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eGrupos\u003c/td\u003e\u003ctd\u003e11°A y 11°B\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eDirigido a\u003c/td\u003e\u003ctd\u003eMicro, pequeñas y medianas empresas (MiPymes) de la región de Boyacá\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eModalidad de trabajo\u003c/td\u003e\u003ctd\u003eEquipos de 3 a 4 aprendices, organizados dentro de cada grupo\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eModalidad de entrega\u003c/td\u003e\u003ctd\u003eDocumento escrito por equipo al instructor, sin sustentación oral\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eProductos del proyecto\u003c/td\u003e\u003ctd\u003e4 productos, en 4 cortes de entrega (ver \"Fechas de entrega\")\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eDuración\u003c/td\u003e\u003ctd\u003eTodo el año lectivo 2026 (último año de contrato del grupo, cierra el 30 de noviembre)\u003c/td\u003e\u003c/tr\u003e\n              \u003c/tbody\u003e\n            \u003c/table\u003e\n          \u003c/div\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003cdiv id=\"presentacion\" class=\"section-title\"\u003ePresentación\u003c/div\u003e\n      \u003cp class=\"section-intro\"\u003e📍 \u003cstrong\u003eEmpieza por aquí:\u003c/strong\u003e conoce de qué trata el taller y qué se espera de tu equipo antes de escoger la MiPyme con la que van a trabajar.\u003c/p\u003e\n      \u003cdiv class=\"gnote gnote--ruta\"\u003e\n        \u003cdiv class=\"gnote__label\"\u003e🧭 ¿Cómo trabajar este taller? Paso a paso\u003c/div\u003e\n        \u003col\u003e\n          \u003cli\u003e\u003cstrong\u003eConforma tu equipo\u003c/strong\u003e de 3 a 4 aprendices dentro de tu grupo (11°A o 11°B).\u003c/li\u003e\n          \u003cli\u003e\u003cstrong\u003eSelecciona una MiPyme real\u003c/strong\u003e de la región de Boyacá como caso de intervención.\u003c/li\u003e\n          \u003cli\u003e\u003cstrong\u003eDesarrolla cada producto en equipo\u003c/strong\u003e, en formato escrito y digital, con evidencia\n          fotográfica y fichas técnicas de las intervenciones realizadas.\u003c/li\u003e\n          \u003cli\u003e\u003cstrong\u003eEntrega cada producto a Drive\u003c/strong\u003e: \u003cu\u003ecada integrante del equipo\u003c/u\u003e sube el mismo\n          documento con el botón \u003cem\u003eEntregar a Drive\u003c/em\u003e, desde su propia cuenta, dentro de la fecha de tu\n          corte.\u003c/li\u003e\n          \u003cli\u003e\u003cstrong\u003eRevisa \"Tu control de avance\"\u003c/strong\u003e (arriba): te muestra qué productos ya entregaste tú\n          y cuáles faltan.\u003c/li\u003e\n        \u003c/ol\u003e\n      \u003c/div\u003e\n      \u003cdiv class=\"gnote gnote--recuerda\"\u003e\u003cdiv class=\"gnote__label\"\u003e💡 Recuerda\u003c/div\u003e\n        \u003cp\u003eEl documento de cada producto es \u003cstrong\u003eun solo documento escrito por equipo\u003c/strong\u003e (todos\n        responden lo mismo, no cada quien el suyo) — pero la \u003cstrong\u003eentrega a Drive es individual\u003c/strong\u003e:\n        cada integrante debe subir ese mismo documento desde su propia cuenta del portal, para que quede\n        registrada la participación de todo el equipo en el control interno del instructor. Si tu equipo\n        ya entregó un producto y necesita corregirlo, pídanle a su instructor que lo habilite de nuevo.\u003c/p\u003e\u003c/div\u003e\n\n      \u003cdiv class=\"card open\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon\" style=\"background:#e3f2fd\"\u003e\u0026#128075;\u003c/div\u003e\n            \u003cdiv\u003e\n              \u003ch3\u003ePresentación inicial\u003c/h3\u003e\n              \u003cp\u003eContexto y sentido del taller\u003c/p\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003cp class=\"intro-text\"\u003e\n            Este taller busca que los aprendices de grado 11° del programa Técnico en Sistemas\n            Teleinformáticos, adscritos a la Institución Educativa Santa Bárbara, desarrollen competencias\n            en diagnóstico, planeación, ejecución y validación del mantenimiento de equipos de cómputo y\n            redes de datos, dirigido a micro, pequeñas y medianas empresas (MiPymes) de la región de\n            Boyacá.\n          \u003c/p\u003e\n          \u003cp class=\"intro-text\"\u003e\n            La mayoría de estas empresas cuenta con infraestructura de equipos y redes, pero recurre\n            principalmente al mantenimiento correctivo en lugar del preventivo, lo que genera sobrecostos,\n            baja disponibilidad de equipos y riesgos en el manejo de la información. Los aprendices\n            intervienen esta problemática real aplicando los conocimientos técnicos adquiridos en el\n            programa de formación.\n          \u003c/p\u003e\n          \u003cdiv class=\"info-box green\" style=\"margin-top:14px\"\u003e\n            \u003cdiv class=\"label\"\u003eObjetivo general\u003c/div\u003e\n            \u003cp\u003e\n              Fortalecer los servicios teleinformáticos de equipos y redes de datos en las MiPymes de la\n              región de Boyacá, mediante el diagnóstico del estado de la infraestructura, el diseño de un\n              plan de mejora, la ejecución del mantenimiento y la validación de los procedimientos\n              realizados.\n            \u003c/p\u003e\n          \u003c/div\u003e\n          \u003cdiv class=\"quote\"\u003e\n            \"Poner el conocimiento al servicio de una empresa real es la mejor forma de comprobar cuánto\n            hemos aprendido.\"\n            \u003ccite\u003eTaller Integrador - Orientación de trabajo\u003c/cite\u003e\n          \u003c/div\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003cdiv class=\"card open\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon\"\u003e\u0026#128101;\u003c/div\u003e\n            \u003cdiv\u003e\n              \u003ch3\u003eMetodología\u003c/h3\u003e\n              \u003cp\u003eCómo se organiza el trabajo en equipo\u003c/p\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003cul class=\"note-list\"\u003e\n            \u003cli\u003eTrabajo en equipos de 3 a 4 aprendices, organizados dentro de cada grupo (11°A y 11°B).\u003c/li\u003e\n            \u003cli\u003eSelección de una MiPyme real de la región de Boyacá como caso de intervención.\u003c/li\u003e\n            \u003cli\u003eElaboración de los productos en formato escrito y digital, con evidencia fotográfica y\n            fichas técnicas de las intervenciones realizadas.\u003c/li\u003e\n            \u003cli\u003eEntrega final de los productos en documento escrito al instructor, sin sustentación oral.\u003c/li\u003e\n          \u003c/ul\u003e\n          \u003cdiv class=\"info-box blue\" style=\"margin-top:14px\"\u003e\n            \u003cp\u003e\u003cstrong\u003eProducto = trabajo de equipo, entrega individual.\u003c/strong\u003e El documento de cada\n            producto es el mismo para todo el equipo, pero \u003cstrong\u003ecada integrante debe entregarlo a Drive\n            desde su propia cuenta\u003c/strong\u003e (mismo archivo, un clic por persona). Así el instructor puede\n            llevar el control interno de que todos entregaron, sin depender de que uno solo suba por todos.\u003c/p\u003e\n          \u003c/div\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003cdiv id=\"equipo\" class=\"card open\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon\"\u003e\u0026#128101;\u003c/div\u003e\n            \u003cdiv\u003e\n              \u003ch3\u003eTu equipo de trabajo\u003c/h3\u003e\n              \u003cp\u003eAntes de empezar, dinos con quién vas a trabajar\u003c/p\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003cdiv class=\"activity open mission-card\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e0\u003c/span\u003e\n              \u003cspan class=\"activity-title\"\u003eConformación del equipo\u003c/span\u003e\n              \u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n              \u003cp class=\"intro-text\"\u003eEscribe los nombres completos de \u003cstrong\u003etodos\u003c/strong\u003e los integrantes de tu\n              equipo, incluyéndote a ti mismo. Esto no reemplaza la portada de cada documento (ahí también deben ir\n              los nombres); es para que tu instructor tenga un registro rápido de qué equipo es cada quien.\u003c/p\u003e\n              \u003clabel\u003e\n                \u003cspan\u003eIntegrantes del equipo (nombres completos, uno por línea o separados por coma)\u003c/span\u003e\n                \u003ctextarea rows=\"3\" data-store=\"equipoTaller\" data-track placeholder=\"Ej: Juan Perez, Maria Lopez, Carlos Gomez\"\u003e\u003c/textarea\u003e\n              \u003c/label\u003e\n              \u003cdiv class=\"act-btn-group\"\u003e\n                \u003cbutton type=\"button\" id=\"btnGuardarEquipoTaller\" class=\"btn-save-response\" onclick=\"actStd_save_equipoTaller()\"\u003e\n                  \u0026#128190; Guardar equipo\n                \u003c/button\u003e\n              \u003c/div\u003e\n              \u003cdiv id=\"statusEquipoTaller\" class=\"activity-saved-notice\" style=\"display:none;margin-top:10px;padding:10px 14px;background:#e8f5e9;border-left:4px solid #2e7d32;border-radius:6px;color:#1b5e20;font-size:0.88rem\"\u003e\n                \u0026#9989; Equipo guardado correctamente.\n              \u003c/div\u003e\n              \u003cdiv data-act-grade=\"equipoTaller\"\u003e\u003c/div\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003cdiv id=\"producto1\" class=\"section-title\"\u003eDesarrollo de los productos del proyecto\u003c/div\u003e\n      \u003cp class=\"section-intro\"\u003e📍 \u003cstrong\u003e4 productos, 4 cortes de entrega:\u003c/strong\u003e cada tarjeta de abajo es un producto distinto. Cuando tu equipo lo tenga listo, súbanlo con el botón \u003cem\u003eEntregar a Drive\u003c/em\u003e de esa tarjeta.\u003c/p\u003e\n\n      \u003cdiv class=\"card open cat-producto1\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon\"\u003e\u0026#128202;\u003c/div\u003e\n            \u003cdiv\u003e\n              \u003ch3\u003eProducto 1 \u0026middot; Informe del estado de la infraestructura\u003c/h3\u003e\n              \u003cp\u003eCorte 1 \u0026middot; Infraestructura, equipos, redes y herramientas\u003c/p\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003cdiv class=\"activity open mission-card\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e1\u003c/span\u003e\n              \u003cspan class=\"activity-title\"\u003eInforme del estado de la infraestructura, equipos, redes y herramientas\u003c/span\u003e\n              \u003cspan class=\"mission-chip\"\u003eCorte 1\u003c/span\u003e\n              \u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n              \u003cp class=\"intro-text\"\u003eDiagnostica el estado actual de la MiPyme que va a acompañar tu equipo durante todo el taller.\u003c/p\u003e\n              \u003cdiv class=\"info-box\" style=\"margin-bottom:16px\"\u003e\n                \u003cdiv class=\"label\"\u003eDebe incluir\u003c/div\u003e\n                \u003cul class=\"note-list\"\u003e\n                  \u003cli\u003eDiagnóstico de la infraestructura de red y equipos informáticos de la MiPyme seleccionada.\u003c/li\u003e\n                  \u003cli\u003eVerificación de la conectividad de la red de acuerdo con la normativa de telecomunicaciones.\u003c/li\u003e\n                  \u003cli\u003eRegistro de solicitudes o requerimientos de servicio técnico presentados por la empresa.\u003c/li\u003e\n                  \u003cli\u003eInventario de herramientas y recursos tecnológicos disponibles.\u003c/li\u003e\n                  \u003cli\u003eConclusiones sobre el estado actual y las necesidades de mantenimiento identificadas.\u003c/li\u003e\n                \u003c/ul\u003e\n              \u003c/div\u003e\n              \u003cdiv class=\"info-box blue\"\u003e\n                \u003cp\u003eEste diagnóstico es la base del Plan de mejora (Producto 2): revísenlo bien antes de avanzar.\u003c/p\u003e\n              \u003c/div\u003e\n              \u003cdiv data-act-std-delivery=\"informeInfraestructura\"\u003e\u003c/div\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003cdiv id=\"producto2\" class=\"card open cat-producto2\" style=\"margin-top:20px;\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon\"\u003e\u0026#128221;\u003c/div\u003e\n            \u003cdiv\u003e\n              \u003ch3\u003eProducto 2 \u0026middot; Plan de mejora\u003c/h3\u003e\n              \u003cp\u003eCorte 2 \u0026middot; Mantenimiento preventivo y correctivo\u003c/p\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003cdiv class=\"activity open mission-card\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e2\u003c/span\u003e\n              \u003cspan class=\"activity-title\"\u003ePlan de mejora\u003c/span\u003e\n              \u003cspan class=\"mission-chip\"\u003eCorte 2\u003c/span\u003e\n              \u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n              \u003cp class=\"intro-text\"\u003eA partir del diagnóstico del Producto 1, diseñen el plan de mejora que van a ejecutar en la MiPyme.\u003c/p\u003e\n              \u003cdiv class=\"info-box\" style=\"margin-bottom:16px\"\u003e\n                \u003cdiv class=\"label\"\u003eDebe incluir\u003c/div\u003e\n                \u003cul class=\"note-list\"\u003e\n                  \u003cli\u003eDefinición de los parámetros y recursos de red requeridos, según normativa de telecomunicaciones.\u003c/li\u003e\n                  \u003cli\u003ePlan de mantenimiento preventivo y correctivo para los equipos de cómputo y redes de datos.\u003c/li\u003e\n                  \u003cli\u003eCronograma de actividades y responsables dentro del equipo de trabajo.\u003c/li\u003e\n                  \u003cli\u003eHerramientas de control propuestas para el seguimiento del plan.\u003c/li\u003e\n                \u003c/ul\u003e\n              \u003c/div\u003e\n              \u003cdiv data-act-std-delivery=\"planMejora\"\u003e\u003c/div\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003cdiv id=\"producto3\" class=\"card open cat-producto3\" style=\"margin-top:20px;\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon\"\u003e\u0026#128295;\u003c/div\u003e\n            \u003cdiv\u003e\n              \u003ch3\u003eProducto 3 \u0026middot; Informe de ejecución\u003c/h3\u003e\n              \u003cp\u003eCorte 3 \u0026middot; Mantenimiento físico y lógico realizado\u003c/p\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003cdiv class=\"activity open mission-card\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e3\u003c/span\u003e\n              \u003cspan class=\"activity-title\"\u003eInforme de ejecución\u003c/span\u003e\n              \u003cspan class=\"mission-chip\"\u003eCorte 3\u003c/span\u003e\n              \u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n              \u003cp class=\"intro-text\"\u003eRegistren la ejecución del plan de mejora en la MiPyme. Este producto cubre el trabajo\n              realizado durante las sesiones de septiembre y octubre, ya que la fase de ejecución es la más extensa\n              del proyecto.\u003c/p\u003e\n              \u003cdiv class=\"info-box\" style=\"margin-bottom:16px\"\u003e\n                \u003cdiv class=\"label\"\u003eDebe incluir\u003c/div\u003e\n                \u003cul class=\"note-list\"\u003e\n                  \u003cli\u003eRegistro del mantenimiento físico y lógico realizado en los equipos de cómputo.\u003c/li\u003e\n                  \u003cli\u003eEvidencia de la implementación de componentes de red (cableado estructurado, puntos de red,\n                  dispositivos inalámbricos, según aplique).\u003c/li\u003e\n                  \u003cli\u003eVerificación de la operación del sistema computacional después del mantenimiento.\u003c/li\u003e\n                  \u003cli\u003eObservaciones y dificultades encontradas durante la ejecución.\u003c/li\u003e\n                \u003c/ul\u003e\n              \u003c/div\u003e\n              \u003cdiv data-act-std-delivery=\"informeEjecucion\"\u003e\u003c/div\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003cp id=\"producto4\" class=\"section-intro\" style=\"margin-top:20px;\"\u003e📍 \u003cstrong\u003eCorte 4, entrega final:\u003c/strong\u003e este producto cierra el taller. Recuerda que este grupo no tiene grado 12° al que trasladar pendientes.\u003c/p\u003e\n      \u003cdiv class=\"card open cat-producto4\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon\"\u003e\u0026#127942;\u003c/div\u003e\n            \u003cdiv\u003e\n              \u003ch3\u003eProducto 4 \u0026middot; Reporte de cumplimiento\u003c/h3\u003e\n              \u003cp\u003eCorte 4 \u0026middot; Validación del plan de mejora (entrega final)\u003c/p\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003cdiv class=\"activity open mission-card\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e4\u003c/span\u003e\n              \u003cspan class=\"activity-title\"\u003eReporte de cumplimiento\u003c/span\u003e\n              \u003cspan class=\"mission-chip\"\u003eCorte 4 · Entrega final\u003c/span\u003e\n              \u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n              \u003cp class=\"intro-text\"\u003eCierren el taller validando lo ejecutado frente al plan de mejora propuesto.\u003c/p\u003e\n              \u003cdiv class=\"info-box\" style=\"margin-bottom:16px\"\u003e\n                \u003cdiv class=\"label\"\u003eDebe incluir\u003c/div\u003e\n                \u003cul class=\"note-list\"\u003e\n                  \u003cli\u003eValidación de los procedimientos realizados frente al plan de mejora propuesto.\u003c/li\u003e\n                  \u003cli\u003eDocumentación de las acciones realizadas en la red, según la normativa técnica.\u003c/li\u003e\n                  \u003cli\u003eResultados alcanzados frente a los objetivos del proyecto.\u003c/li\u003e\n                  \u003cli\u003eRecomendaciones para la MiPyme y lecciones aprendidas por el equipo.\u003c/li\u003e\n                \u003c/ul\u003e\n              \u003c/div\u003e\n              \u003cdiv data-act-std-delivery=\"reporteCumplimiento\"\u003e\u003c/div\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003cdiv id=\"requisitos\" class=\"section-title\"\u003eRequisitos formales de entrega\u003c/div\u003e\n      \u003cp class=\"section-intro\"\u003e📍 \u003cstrong\u003eAplica a los 4 productos:\u003c/strong\u003e cada producto debe presentarse de manera individual (por equipo de trabajo) y cumplir con esta misma estructura y formato.\u003c/p\u003e\n      \u003cdiv class=\"gnote gnote--ruta\"\u003e\n        \u003cdiv class=\"gnote__label\"\u003e🧭 Así se arma el documento, en este orden\u003c/div\u003e\n        \u003cp\u003eCada uno de los 4 productos es \u003cstrong\u003eun solo documento\u003c/strong\u003e (no cuatro documentos separados),\n        con las partes 1 a 6 de abajo \u003cstrong\u003een ese orden, una detrás de la otra\u003c/strong\u003e. Los anexos (si\n        aplican) van al final, después de las referencias. El formato (letra, márgenes, interlineado) no es\n        una parte más: son las reglas que debes aplicar a \u003cstrong\u003etodo\u003c/strong\u003e el documento, de la portada\n        a la última página.\u003c/p\u003e\n      \u003c/div\u003e\n\n      \u003cdiv class=\"panel-grid-single\"\u003e\n        \u003carticle class=\"checklist-card\"\u003e\n          \u003ch3\u003e1\u0026#65039;\u0026#8419; \u0026#128196; Portada\u003c/h3\u003e\n          \u003cul class=\"note-list\"\u003e\n            \u003cli\u003eNombre de la institución (SENA \u0026ndash; Centro de Formación).\u003c/li\u003e\n            \u003cli\u003ePrograma de formación: Técnico en Sistemas Teleinformáticos.\u003c/li\u003e\n            \u003cli\u003eTítulo del trabajo.\u003c/li\u003e\n            \u003cli\u003eInstitución educativa: Santa Bárbara (SB), grado 11° (grupo 11°A o 11°B).\u003c/li\u003e\n            \u003cli\u003eNombre completo de los integrantes del equipo.\u003c/li\u003e\n            \u003cli\u003eNombre del instructor.\u003c/li\u003e\n            \u003cli\u003eLugar y fecha de entrega.\u003c/li\u003e\n          \u003c/ul\u003e\n        \u003c/article\u003e\n        \u003carticle class=\"checklist-card\"\u003e\n          \u003ch3\u003e2\u0026#65039;\u0026#8419; \u0026#128209; Tabla de contenido\u003c/h3\u003e\n          \u003cul class=\"note-list\"\u003e\n            \u003cli\u003eÍndice organizado con numeración de páginas.\u003c/li\u003e\n            \u003cli\u003eUso de títulos y subtítulos jerarquizados.\u003c/li\u003e\n          \u003c/ul\u003e\n        \u003c/article\u003e\n        \u003carticle class=\"checklist-card\"\u003e\n          \u003ch3\u003e3\u0026#65039;\u0026#8419; \u0026#128075; Introducción\u003c/h3\u003e\n          \u003cul class=\"note-list\"\u003e\n            \u003cli\u003eBreve explicación del propósito del trabajo.\u003c/li\u003e\n            \u003cli\u003eContexto de la MiPyme intervenida.\u003c/li\u003e\n            \u003cli\u003eAlcance y limitaciones del producto.\u003c/li\u003e\n          \u003c/ul\u003e\n        \u003c/article\u003e\n        \u003carticle class=\"checklist-card\"\u003e\n          \u003ch3\u003e4\u0026#65039;\u0026#8419; \u0026#128221; Desarrollo\u003c/h3\u003e\n          \u003cul class=\"note-list\"\u003e\n            \u003cli\u003eExposición clara y ordenada de la información.\u003c/li\u003e\n            \u003cli\u003eUso de subtítulos para organizar ideas.\u003c/li\u003e\n            \u003cli\u003eEjemplos, cuadros, tablas, fotografías o diagramas que apoyen el análisis.\u003c/li\u003e\n            \u003cli\u003eAplicación de conceptos vistos en la formación.\u003c/li\u003e\n          \u003c/ul\u003e\n        \u003c/article\u003e\n        \u003carticle class=\"checklist-card\"\u003e\n          \u003ch3\u003e5\u0026#65039;\u0026#8419; \u0026#9989; Conclusiones\u003c/h3\u003e\n          \u003cul class=\"note-list\"\u003e\n            \u003cli\u003eReflexiones finales sobre el aprendizaje obtenido.\u003c/li\u003e\n            \u003cli\u003eResultados alcanzados en relación con el objetivo del trabajo.\u003c/li\u003e\n            \u003cli\u003ePosibles recomendaciones para la MiPyme o el proceso analizado.\u003c/li\u003e\n          \u003c/ul\u003e\n        \u003c/article\u003e\n        \u003carticle class=\"checklist-card\"\u003e\n          \u003ch3\u003e6\u0026#65039;\u0026#8419; \u0026#128279; Referencias bibliográficas\u003c/h3\u003e\n          \u003cul class=\"note-list\"\u003e\n            \u003cli\u003eFuentes consultadas (manuales técnicos, normativa de telecomunicaciones, documentos institucionales).\u003c/li\u003e\n            \u003cli\u003eNormas APA (última edición) o lineamientos institucionales.\u003c/li\u003e\n          \u003c/ul\u003e\n        \u003c/article\u003e\n        \u003carticle class=\"checklist-card\"\u003e\n          \u003ch3\u003e\u0026#128193; Anexos \u003cspan style=\"font-weight:400\"\u003e\u0026mdash; opcional, va al final\u003c/span\u003e\u003c/h3\u003e\n          \u003cul class=\"note-list\"\u003e\n            \u003cli\u003eDocumentos, formatos, fichas técnicas, fotografías o evidencias adicionales.\u003c/li\u003e\n          \u003c/ul\u003e\n        \u003c/article\u003e\n      \u003c/div\u003e\n\n      \u003cdiv class=\"info-box blue\" style=\"margin-top:16px\"\u003e\n        \u003cdiv class=\"label\"\u003e\u0026#128207; Formato para TODO el documento (de la portada a la última página)\u003c/div\u003e\n        \u003cp\u003eEsto no es una parte más de la lista de arriba: son las reglas de presentación que debes usar en\n        \u003cstrong\u003etodo\u003c/strong\u003e el documento, desde la portada hasta el final.\u003c/p\u003e\n        \u003cul class=\"note-list\"\u003e\n          \u003cli\u003eLetra Arial 12.\u003c/li\u003e\n          \u003cli\u003eInterlineado 1.5.\u003c/li\u003e\n          \u003cli\u003eMárgenes estándar (2.5 cm).\u003c/li\u003e\n          \u003cli\u003eNumeración de páginas.\u003c/li\u003e\n          \u003cli\u003eJustificación del texto.\u003c/li\u003e\n        \u003c/ul\u003e\n      \u003c/div\u003e\n\n      \u003cdiv id=\"fechas\" class=\"section-title\"\u003eFechas de entrega por grupo\u003c/div\u003e\n      \u003cp class=\"section-intro\"\u003e📍 \u003cstrong\u003eUn corte por producto.\u003c/strong\u003e Las fechas corresponden al último día de la sesión de clase disponible en cada corte, según el calendario real de clases de 11°A y 11°B.\u003c/p\u003e\n      \u003cdiv class=\"card open\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon\" style=\"background:#fff3e0\"\u003e\u0026#128197;\u003c/div\u003e\n            \u003cdiv\u003e\n              \u003ch3\u003eCalendario de cortes 2026\u003c/h3\u003e\n              \u003cp\u003eSegún el calendario de clases de cada grupo\u003c/p\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003cdiv class=\"table-scroll\"\u003e\n            \u003ctable class=\"data-table\"\u003e\n              \u003cthead\u003e\n                \u003ctr\u003e\u003cth\u003eCorte \u0026middot; Producto\u003c/th\u003e\u003cth\u003eFecha límite \u0026middot; \u003cspan data-grupo-label\u003etu grupo\u003c/span\u003e\u003c/th\u003e\u003c/tr\u003e\n              \u003c/thead\u003e\n              \u003ctbody\u003e\n                \u003ctr\u003e\u003ctd\u003eCorte 1 \u0026ndash; Producto 1: Informe del estado de la infraestructura, equipos, redes y herramientas\u003c/td\u003e\u003ctd data-fecha-11a=\"31-jul-2026\" data-fecha-11b=\"30-jul-2026\"\u003e31-jul-2026\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eCorte 2 \u0026ndash; Producto 2: Plan de mejora\u003c/td\u003e\u003ctd data-fecha-11a=\"28-ago-2026\" data-fecha-11b=\"27-ago-2026\"\u003e28-ago-2026\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eCorte 3 \u0026ndash; Producto 3: Informe de ejecución\u003c/td\u003e\u003ctd data-fecha-11a=\"23-oct-2026\" data-fecha-11b=\"22-oct-2026\"\u003e23-oct-2026\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eCorte 4 \u0026ndash; Producto 4: Reporte de cumplimiento (entrega final)\u003c/td\u003e\u003ctd data-fecha-11a=\"27-nov-2026\" data-fecha-11b=\"26-nov-2026\"\u003e27-nov-2026\u003c/td\u003e\u003c/tr\u003e\n              \u003c/tbody\u003e\n            \u003c/table\u003e\n          \u003c/div\u003e\n          \u003cdiv class=\"gnote gnote--recuerda\" style=\"margin-top:14px\"\u003e\u003cdiv class=\"gnote__label\"\u003e\u0026#9888; Nota\u003c/div\u003e\n            \u003cp\u003eEste es el último año de contrato de estos grupos (finaliza el 30 de noviembre de 2026), por\n            lo que el Producto 4 debe quedar cerrado en ese corte: \u003cstrong\u003eno hay grado 12° al cual\n            trasladar pendientes\u003c/strong\u003e. El instructor puede adelantar la asignación del producto en la\n            sesión anterior para dar tiempo de desarrollo, y puede habilitar de nuevo un producto ya\n            entregado si tu equipo necesita corregirlo.\u003c/p\u003e\u003c/div\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003cdiv id=\"evaluacion\" class=\"section-title\"\u003eEvaluación\u003c/div\u003e\n      \u003cdiv class=\"card open cat-evaluacion\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon\" style=\"background:#f3e5f5\"\u003e\u0026#127919;\u003c/div\u003e\n            \u003cdiv\u003e\n              \u003ch3\u003eCriterios de evaluación\u003c/h3\u003e\n              \u003cp\u003eQué revisa el instructor en cada producto\u003c/p\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003cul class=\"note-list\"\u003e\n            \u003cli\u003eClaridad y organización de los informes.\u003c/li\u003e\n            \u003cli\u003eRigor técnico en el diagnóstico y en el mantenimiento realizado.\u003c/li\u003e\n            \u003cli\u003eEvidencia real de la intervención (fotografías, fichas técnicas, registros de mantenimiento).\u003c/li\u003e\n            \u003cli\u003eCumplimiento del plan de mejora propuesto.\u003c/li\u003e\n            \u003cli\u003eCalidad de la entrega final.\u003c/li\u003e\n          \u003c/ul\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003cdiv class=\"gnote gnote--entrega\"\u003e\u003cdiv class=\"gnote__label\"\u003e📦 Antes de entregar, revisa\u003c/div\u003e\n        \u003cul\u003e\n          \u003cli\u003eEl documento cumple la portada, tabla de contenido, introducción, desarrollo, conclusiones, referencias y formato exigidos.\u003c/li\u003e\n          \u003cli\u003eEl archivo lleva el nombre completo de todos los integrantes del equipo en la portada.\u003c/li\u003e\n          \u003cli\u003e\u003cstrong\u003eCada integrante del equipo\u003c/strong\u003e entró a su propia cuenta y subió el mismo documento con el botón \u003cem\u003eEntregar a Drive\u003c/em\u003e de esa tarjeta, para que a todos les quede marcado como \u003cstrong\u003eEntregada\u003c/strong\u003e en su control de avance.\u003c/li\u003e\n        \u003c/ul\u003e\n      \u003c/div\u003e\n\n    \u003c/div\u003e\n  \u003c/main\u003e\n\u003c/div\u003e\n\n\u003cscript\u003e\n(function () {\n  function buildGuideRouteHref(fileName) {\n    return \"guia.html?g=\" + encodeURIComponent(fileName);\n  }\n\n  var grupo = String((document.body \u0026\u0026 document.body.dataset \u0026\u0026 document.body.dataset.defaultGrupo) || \"11A\").toUpperCase();\n  var esGrupoB = grupo === \"11B\";\n\n  // Tabla de fechas: cada celda trae AMBAS fechas en data-*; aqui se deja\n  // visible solo la del grupo real del aprendiz (no se muestra la del otro grupo).\n  document.querySelectorAll(\"[data-fecha-11a]\").forEach(function (cell) {\n    var fecha = esGrupoB ? cell.getAttribute(\"data-fecha-11b\") : cell.getAttribute(\"data-fecha-11a\");\n    if (fecha) cell.textContent = fecha;\n  });\n  document.querySelectorAll(\"[data-grupo-label]\").forEach(function (span) {\n    span.textContent = \"Grupo \" + grupo;\n  });\n\n  var config = {\n    \"11A\": {\n      currentFile: \"grupo-11a-guia-09-taller-integrador.html\",\n      currentLabel: \"Taller Integrador | 11A\",\n      campus: \"Santa Bárbara | 11A\"\n    },\n    \"11B\": {\n      currentFile: \"grupo-11b-guia-09-taller-integrador.html\",\n      currentLabel: \"Taller Integrador | 11B\",\n      campus: \"Santa Bárbara | 11B\"\n    }\n  }[grupo] || null;\n\n  if (!config) {\n    return;\n  }\n\n  var currentGuideNavLink = document.getElementById(\"currentGuideNavLink\");\n  var currentGuideNavLabel = document.getElementById(\"currentGuideNavLabel\");\n  var topbarCampus = document.getElementById(\"topbarCampus\");\n\n  if (currentGuideNavLink) {\n    currentGuideNavLink.href = buildGuideRouteHref(config.currentFile);\n    currentGuideNavLink.dataset.currentFile = config.currentFile;\n  }\n  if (currentGuideNavLabel) {\n    currentGuideNavLabel.textContent = config.currentLabel;\n  }\n  if (topbarCampus) {\n    topbarCampus.textContent = config.campus;\n  }\n})();\n\u003c/script\u003e\n";
